func (r *mutationResolver) EndWorkerShiftAssignment(ctx context.Context, id string, effectiveTo int) (*worker.WorkerShiftAssignment, error) {
	assignmentID, err := pulid.MustParse(id)
	if err != nil {
		return nil, invalidIDError("id", "Assignment is invalid")
	}

	authCtx, err := r.requireAuth(ctx)
	if err != nil {
		return nil, err
	}

	assignment, err := r.schedulingService.GetAssignment(ctx, tenantInfo(authCtx), assignmentID)
	if err != nil {
		return nil, err
	}

	// The worker is read off the assignment rather than taken from the caller:
	// an id supplied alongside the one being acted on is an id somebody can lie
	// about.
	if _, _, err = r.requireTeamScope(
		ctx,
		permission.ResourceWorkerSchedule,
		permission.OpAssign,
		worker.ApprovalScopeAll,
		assignment.WorkerID,
	); err != nil {
		return nil, err
	}

	return r.schedulingService.EndAssignment(ctx, &schedulingservice.EndAssignmentRequest{
		ID:          assignmentID,
		EffectiveTo: int64(effectiveTo),
		TenantInfo:  tenantInfo(authCtx),
		UserID:      authCtx.UserID,
	})
}

