func (r *queryResolver) Rota(ctx context.Context, filter *gqlmodel.RotaFilterInput) (*gqlmodel.Rota, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceWorkerSchedule, permission.OpRead)
	if err != nil {
		return nil, err
	}

	req := &schedulingservice.RotaRequest{TenantInfo: tenantInfo(authCtx)}
	if filter != nil {
		req.At = int64Value(filter.At)
		req.Weeks = intValue(filter.Weeks)
		req.Limit = intValue(filter.Limit)
		if req.FleetCodeID, err = optionalID(filter.FleetCodeID); err != nil {
			return nil, invalidIDError("fleetCodeId", "Fleet is invalid")
		}
		if req.WorkerIDs, err = parseIDList(filter.WorkerIds); err != nil {
			return nil, invalidIDError("workerIds", "Worker is invalid")
		}
		if boolValue(filter.TeamOnly) {
			if req.ManagerIDs, err = r.rotaManagerIDs(ctx, authCtx.UserID, tenantInfo(authCtx)); err != nil {
				return nil, err
			}
		}
	}

	rota, err := r.schedulingService.Rota(ctx, req)
	if err != nil {
		return nil, err
	}

	return rotaToGQL(rota), nil
}

func (r *shiftTemplateResolver) ActiveAssignmentCount(ctx context.Context, obj *worker.ShiftTemplate) (int, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceShiftTemplate, permission.OpRead)
	if err != nil {
		return 0, err
	}
	if l, ok := loaders.FromContext(ctx); ok && l != nil {
		return l.ShiftTemplateActiveAssignmentCount.Load(ctx, obj.ID.String())
	}

	return r.schedulingService.CountTemplateAssignments(ctx, tenantInfo(authCtx), obj.ID)
}

